      await until(()=>js('!!document.querySelector(".ui-action-menu")&&!!document.querySelector(".browser-frozen-frame")?.naturalWidth'),'workspace menu preserves the page image')
      await until(()=>Promise.resolve(!nativeVisible()),'covered native view yields input to the menu')
      const menu=await js('(()=>{const menu=document.querySelector(".ui-action-menu");return {display:getComputedStyle(menu).display,rows:[...menu.querySelectorAll("button")].map(b=>b.getBoundingClientRect().toJSON())}})()')
      assert.equal(menu.display,'flex','Teleported menus retain their layout styles')
      assert.ok(menu.rows.every((row:any,index:number)=>!index||row.top>=menu.rows[index-1].bottom),'Menu actions appear in separate vertical rows')
      await until(()=>js('Number(getComputedStyle(document.querySelector(".ui-action-menu").closest(".v-overlay__content")).opacity)>.99'),'menu opening transition settled')
      fs.writeFileSync(path.join(output,'workspace-menu-preserves-page.png'),(await win.webContents.capturePage()).toPNG())
      const menuShot=await js(`(()=>{const r=document.querySelector('.ui-action-menu').getBoundingClientRect();return {x:Math.max(0,Math.floor(r.x)-18),y:Math.max(0,Math.floor(r.y)-18),width:Math.ceil(r.width)+36,height:Math.ceil(r.height)+36}})()`)
      fs.writeFileSync(path.join(output,'workspace-menu-detail.png'),(await win.webContents.capturePage(menuShot)).toPNG())
      win.webContents.sendInputEvent({type:'keyDown',keyCode:'Escape'});win.webContents.sendInputEvent({type:'keyUp',keyCode:'Escape'})
