      await until(()=>js('!document.querySelector("[aria-label=浏览器后退]").disabled'),'manual navigation history reaches toolbar')
      await js('document.querySelector("[aria-label=浏览器后退]").click()')
      await until(()=>Promise.resolve(guest.getURL()===url),'manual back navigation')
      await js(`window.slowNavigation=window.navora.browser.workspace.command(window.testPageId,'navigate',${JSON.stringify(url.replace('/page','/slow'))}).then(()=>true,e=>String(e));true`)
      await until(()=>js('!!document.querySelector("[aria-label=停止加载网页]")'),'manual control can stop an incomplete load')
      await js('document.querySelector("[aria-label=停止加载网页]").click()')
